 import { App, PostMessageTransport } from "@modelcontextprotocol/ext-apps";
 import {
 	createContext,
 	type FC,
 	type ReactNode,
 	useContext,
 	useEffect,
+	useRef,
 	useState,
 } from "react";
 import { createRoot } from "react-dom/client";
 import {
 	approvalCapabilityFromMeta,
+	persistOpenAiViewSnapshot,
 	readOpenAiCompatSnapshot,
 } from "./openai-compat";
 import { isExternalHttpUrl } from "./view";

 /** Shared iframe-side runtime for every Lobu MCP App bundle. */

 type ToolArgs = Record<string, unknown>;

 interface McpAppApi<T> {
 	/** Server-authored LobuViewV1 from the originating tool result. */
 	data: T | null;
 	/** Ask the host to broker a standard MCP `tools/call`. */
 	callTool: (name: string, args: ToolArgs) => Promise<void>;
 	/** Ask the host to open an external URL via `ui/open-link`. */
 	openLink: (href: string) => Promise<void>;
 	/** Latest app-initiated tool result; `seq` bumps so effects react to retries. */
 	lastResult: { isError: boolean; seq: number } | null;
 	/** True only inside Lobu's same-origin SPA parent, never in an external host. */
 	allowSpaHostedViews: boolean;
 }

 const McpAppContext = createContext<McpAppApi<unknown>>({
 	data: null,
 	callTool: async () => {},
 	openLink: async () => {},
 	lastResult: null,
 	allowSpaHostedViews: false,
 });

 /** Typed accessor for the host bridge inside a bundle's card component. */
 export function useMcpApp<T>(): McpAppApi<T> {
 	return useContext(McpAppContext) as McpAppApi<T>;
 }

 const isEmbedded = window.parent !== window;
 const OPENAI_SET_GLOBALS_EVENT = "openai:set_globals";

 type OpenAiCompatWindow = Window & { openai?: unknown };
 type OpenAiSetGlobalsEvent = CustomEvent<{ globals?: unknown }>;

 function openAiCompatTargets(): OpenAiCompatWindow[] {
 	const ownWindow = window as OpenAiCompatWindow;
 	if (!isEmbedded) return [ownWindow];
 	try {
 		if (window.parent.location.origin === window.location.origin) {
 			return [ownWindow, window.parent as OpenAiCompatWindow];
 		}
 	} catch {
 		// A cross-origin parent is the standard portable MCP Apps topology.
 	}
 	return [ownWindow];
 }

 function currentOpenAiGlobals(targets = openAiCompatTargets()): unknown {
 	let fallback: unknown;
+	let widgetStateFallback: unknown;
 	for (const target of targets) {
 		const candidate = target.openai;
 		if (candidate === undefined) continue;
 		fallback ??= candidate;
 		if (
 			isStructuredObject(candidate) &&
 			(Object.hasOwn(candidate, "toolOutput") ||
 				Object.hasOwn(candidate, "toolResponseMetadata"))
 		) {
 			return candidate;
 		}
+		if (
+			isStructuredObject(candidate) &&
+			Object.hasOwn(candidate, "widgetState")
+		) {
+			widgetStateFallback ??= candidate;
+		}
+	}
+	return widgetStateFallback ?? fallback;
+}
+
+function persistOpenAiData<T>(
+	targets: OpenAiCompatWindow[],
+	data: T | null,
+): void {
+	for (const target of targets) {
+		if (persistOpenAiViewSnapshot(target.openai, data)) return;
 	}
-	return fallback;
 }

 function hasSameOriginParent(): boolean {
 	if (!isEmbedded) return true;
 	try {
 		return window.parent.location.origin === window.location.origin;
 	} catch {
 		return false;
 	}
 }

 function isStructuredObject(value: unknown): value is Record<string, unknown> {
 	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
 }

 function applyTheme(theme: "light" | "dark" | undefined): void {
 	const dark = theme
 		? theme === "dark"
 		: window.matchMedia("(prefers-color-scheme: dark)").matches;
 	document.documentElement.classList.toggle("dark", dark);
 }

 export function Provider<T>({
 	devMock,
 	children,
 }: {
 	devMock: T;
 	children: ReactNode;
 }) {
 	const [initialCompat] = useState(() =>
 		readOpenAiCompatSnapshot<T>(currentOpenAiGlobals()),
 	);
 	const [data, setData] = useState<T | null>(
 		isEmbedded ? (initialCompat.data ?? null) : devMock,
 	);
 	const [lastResult, setLastResult] = useState<{
 		isError: boolean;
 		seq: number;
 	} | null>(null);
 	const [app, setApp] = useState<App | null>(null);
 	const [approvalCapability, setApprovalCapability] = useState<string | null>(
 		initialCompat.approvalCapability ?? null,
 	);
+	const hasLiveToolOutput = useRef(false);
 	const allowSpaHostedViews = hasSameOriginParent();

 	useEffect(() => {
 		if (!isEmbedded) {
 			applyTheme(undefined);
 			return;
 		}

 		const compatTargets = openAiCompatTargets();
 		const nextApp = new App(
 			{ name: "Lobu Interaction", version: "1.0.0" },
 			{},
 			{ autoResize: true, strict: true },
 		);
 		const transport = new PostMessageTransport(window.parent, window.parent);
 		const onToolResult = (params: {
 			structuredContent?: unknown;
 			_meta?: unknown;
 		}) => {
 			if (isStructuredObject(params.structuredContent)) {
-				setData(params.structuredContent as T);
+				const nextData = params.structuredContent as T;
+				hasLiveToolOutput.current = true;
+				setData(nextData);
+				persistOpenAiData(compatTargets, nextData);
 			}
 			setApprovalCapability(approvalCapabilityFromMeta(params._meta));
 		};
 		const onHostContext = (params: { theme?: "light" | "dark" }) =>
 			applyTheme(params.theme);
-		const applyOpenAiGlobals = (globals: unknown) => {
+		const applyOpenAiGlobals = (
+			globals: unknown,
+			persistInitialData = false,
+		) => {
 			const snapshot = readOpenAiCompatSnapshot<T>(globals);
-			if (snapshot.data !== undefined) setData(snapshot.data);
+			const includesToolOutput =
+				isStructuredObject(globals) && Object.hasOwn(globals, "toolOutput");
+			if (includesToolOutput) hasLiveToolOutput.current = true;
+			if (snapshot.data !== undefined) {
+				// setWidgetState echoes a widgetState-only event. Never let that
+				// display-safe cache replace a live result in the current lifetime.
+				if (includesToolOutput || !hasLiveToolOutput.current) {
+					setData(snapshot.data);
+				}
+				if (persistInitialData) {
+					persistOpenAiData(compatTargets, snapshot.data);
+				}
+			}
 			if (snapshot.approvalCapability !== undefined) {
 				setApprovalCapability(snapshot.approvalCapability);
 			}
 		};
 		const onOpenAiSetGlobals = (event: Event) => {
 			const detail = (event as OpenAiSetGlobalsEvent).detail;
 			if (isStructuredObject(detail) && "globals" in detail) {
 				applyOpenAiGlobals(detail.globals);
 			}
 		};
 		nextApp.addEventListener("toolresult", onToolResult);
 		nextApp.addEventListener("hostcontextchanged", onHostContext);
 		for (const target of compatTargets) {
 			target.addEventListener(OPENAI_SET_GLOBALS_EVENT, onOpenAiSetGlobals);
 		}
-		applyOpenAiGlobals(currentOpenAiGlobals(compatTargets));
+		// Persist preloaded output once. Later compatibility events are read-only:
+		// setWidgetState itself publishes an openai:set_globals widgetState update.
+		applyOpenAiGlobals(currentOpenAiGlobals(compatTargets), true);
 		setApp(nextApp);
 		void nextApp
 			.connect(transport)
 			.then(() => applyTheme(nextApp.getHostContext()?.theme))
 			.catch((error) => {
 				console.error("[mcp-app] failed to initialize", error);
 			});

 		return () => {
 			nextApp.removeEventListener("toolresult", onToolResult);
 			nextApp.removeEventListener("hostcontextchanged", onHostContext);
 			for (const target of compatTargets) {
 				target.removeEventListener(
 					OPENAI_SET_GLOBALS_EVENT,
 					onOpenAiSetGlobals,
 				);
 			}
 			void transport.close();
 		};
 	}, []);

 	const callTool = async (name: string, args: ToolArgs) => {
 		if (!app) {
 			if (!isEmbedded) {
 				console.log("[mcp-app] tools/call", name, args);
 				setLastResult((last) => ({
 					isError: false,
 					seq: (last?.seq ?? 0) + 1,
 				}));
 			}
 			return;
 		}
 		try {
 			const result = await app.callServerTool({
 				name,
 				arguments: args,
 				...(name === "resolve_lobu_approval" && approvalCapability
 					? { _meta: { "lobu/approval-capability": approvalCapability } }
 					: {}),
 			});
 			if (isStructuredObject(result.structuredContent)) {
-				setData(result.structuredContent as T);
+				const nextData = result.structuredContent as T;
+				hasLiveToolOutput.current = true;
+				setData(nextData);
+				persistOpenAiData(openAiCompatTargets(), nextData);
 			}
 			if (name === "resolve_lobu_approval" && result.isError !== true) {
 				setApprovalCapability(null);
 			}
 			setLastResult((last) => ({
 				isError: result.isError === true,
 				seq: (last?.seq ?? 0) + 1,
 			}));
 		} catch {
 			setLastResult((last) => ({
 				isError: true,
 				seq: (last?.seq ?? 0) + 1,
 			}));
 		}
 	};

 	const openLink = async (href: string) => {
 		if (!isExternalHttpUrl(href)) {
 			console.warn("[mcp-app] refused non-HTTP external link");
 			return;
 		}
 		if (!app) {
 			if (!isEmbedded) console.log("[mcp-app] ui/open-link", href);
 			return;
 		}
 		try {
 			const result = await app.openLink({ url: href });
 			if (result.isError) console.warn("[mcp-app] host rejected external link");
 		} catch {
 			console.warn("[mcp-app] host rejected external link");
 		}
 	};

 	return (
 		<McpAppContext.Provider
 			value={{ data, callTool, openLink, lastResult, allowSpaHostedViews }}
 		>
 			{children}
 		</McpAppContext.Provider>
 	);
 }

 /** Mount a bundle's card as a standalone MCP App with the standard bridge. */
 export function mountMcpApp<T>(opts: { devMock: T; App: FC }): void {
 	const { devMock, App: View } = opts;
 	createRoot(document.getElementById("root") as HTMLElement).render(
 		<Provider devMock={devMock}>
 			<View />
 		</Provider>,
 	);
 }
diff --git a/src/mcp-apps/_shared/openai-compat.ts b/src/mcp-apps/_shared/openai-compat.ts
index 3ca9f16d..e769fdc1 100644
--- a/src/mcp-apps/_shared/openai-compat.ts
+++ b/src/mcp-apps/_shared/openai-compat.ts
@@ -1,59 +1,146 @@
 type UnknownRecord = Record<string, unknown>;

+const LOBU_VIEW_SNAPSHOT_KEY = "lobuViewSnapshot";
+const LOBU_VIEW_SNAPSHOT_VERSION = 1;
+
 export interface OpenAiCompatSnapshot<T> {
 	/** `undefined` means the host did not update this global. */
 	data: T | null | undefined;
 	/** `undefined` means the host did not update this global. */
 	approvalCapability: string | null | undefined;
 }

 function isStructuredObject(value: unknown): value is UnknownRecord {
 	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
 }

 export function approvalCapabilityFromMeta(meta: unknown): string | null {
 	if (!isStructuredObject(meta)) return null;
 	const token = meta["lobu/approval-capability"];
 	return typeof token === "string" && token.length <= 4_096 ? token : null;
 }

 function approvalCapabilityFromResult(result: unknown): string | null {
 	if (!isStructuredObject(result)) return null;
 	return approvalCapabilityFromMeta(result._meta);
 }

+function dataFromToolOutput<T>(toolOutput: unknown): T | null {
+	if (!isStructuredObject(toolOutput)) return null;
+	if (Object.hasOwn(toolOutput, "structuredContent")) {
+		return isStructuredObject(toolOutput.structuredContent)
+			? (toolOutput.structuredContent as T)
+			: null;
+	}
+	return toolOutput as T;
+}
+
+function dataFromWidgetState<T>(widgetState: unknown): T | null | undefined {
+	if (!isStructuredObject(widgetState)) return undefined;
+	const privateContent = widgetState.privateContent;
+	if (!isStructuredObject(privateContent)) return undefined;
+	const snapshot = privateContent[LOBU_VIEW_SNAPSHOT_KEY];
+	if (!isStructuredObject(snapshot)) return undefined;
+	if (snapshot.version !== LOBU_VIEW_SNAPSHOT_VERSION) return undefined;
+	return snapshot.data === null
+		? null
+		: isStructuredObject(snapshot.data)
+			? (snapshot.data as T)
+			: undefined;
+}
+
+function displaySafeSnapshotData<T>(data: T | null): T | null {
+	if (!isStructuredObject(data) || !Array.isArray(data.actions)) return data;
+	return {
+		...data,
+		actions: data.actions.filter(
+			(action) =>
+				!isStructuredObject(action) || action.tool !== "resolve_lobu_approval",
+		),
+	} as T;
+}
+
+/**
+ * Cache the latest server-authored view in ChatGPT's per-widget UI state. The
+ * snapshot is a display-only reload fallback; a fresh tool result always wins.
+ * Hidden result metadata is deliberately excluded.
+ */
+export function persistOpenAiViewSnapshot<T>(
+	globals: unknown,
+	data: T | null,
+): boolean {
+	if (!isStructuredObject(globals)) return false;
+	const setWidgetState = globals.setWidgetState;
+	if (typeof setWidgetState !== "function") return false;
+
+	const widgetState = isStructuredObject(globals.widgetState)
+		? globals.widgetState
+		: {};
+	const privateContent = isStructuredObject(widgetState.privateContent)
+		? widgetState.privateContent
+		: {};
+	const nextWidgetState = {
+		...widgetState,
+		privateContent: {
+			...privateContent,
+			[LOBU_VIEW_SNAPSHOT_KEY]: {
+				version: LOBU_VIEW_SNAPSHOT_VERSION,
+				data: displaySafeSnapshotData(data),
+			},
+		},
+	};
+
+	try {
+		const result = Reflect.apply(setWidgetState, globals, [nextWidgetState]);
+		if (isStructuredObject(result) && typeof result.catch === "function") {
+			void Reflect.apply(result.catch, result, [() => {}]);
+		}
+		return true;
+	} catch {
+		return false;
+	}
+}
+
 /**
  * Read ChatGPT's compatibility globals without making them a dependency of the
  * portable MCP Apps bridge. ChatGPT restores these globals for historical
  * cards, including after the standard tool-result notification has already
  * happened in an earlier page lifetime.
  */
 export function readOpenAiCompatSnapshot<T>(
 	globals: unknown,
 ): OpenAiCompatSnapshot<T> {
 	if (!isStructuredObject(globals)) {
 		return { data: undefined, approvalCapability: undefined };
 	}

 	const hasToolOutput = Object.hasOwn(globals, "toolOutput");
-	const data = hasToolOutput
-		? isStructuredObject(globals.toolOutput)
-			? (globals.toolOutput as T)
-			: null
-		: undefined;
+	const hasFullToolResult =
+		hasToolOutput &&
+		isStructuredObject(globals.toolOutput) &&
+		Object.hasOwn(globals.toolOutput, "structuredContent");
+	const outputData = hasToolOutput
+		? dataFromToolOutput<T>(globals.toolOutput)
+		: dataFromWidgetState<T>(globals.widgetState);
 	const hasToolResponseMetadata = Object.hasOwn(
 		globals,
 		"toolResponseMetadata",
 	);
 	const metadata = isStructuredObject(globals.toolResponseMetadata)
 		? globals.toolResponseMetadata
 		: null;
 	const approvalCapability = hasToolResponseMetadata
 		? metadata
 			? (approvalCapabilityFromResult(metadata.mcp_tool_result) ??
 				approvalCapabilityFromResult(metadata.call_tool_result))
 			: null
-		: undefined;
+		: hasFullToolResult
+			? approvalCapabilityFromResult(globals.toolOutput)
+			: undefined;
+	const data =
+		hasToolOutput && approvalCapability === null
+			? displaySafeSnapshotData(outputData)
+			: outputData;

 	return { data, approvalCapability };
 }

