   506	              code,
   507	              retryable: error.retryable as boolean,
   508	              ...(error.callId ? { call_id: error.callId as string } : {}),
   509	            }
   510	          : undefined;
   511	      return {
   512	        content: [
   513	          {
   514	            type: 'text' as const,
   515	            text: error.message ?? 'Tool execution failed',
   516	          },
   517	        ],
   518	        isError: true,
   519	        ...(structuredError ? { structuredContent: { error: structuredError } } : {}),
   520	        ...(scopeChallenge ? { _meta: { 'mcp/www_authenticate': [scopeChallenge] } } : {}),
   521	      };
   522	    }
   523	  });
   524	
   525	  return server;
   526	}
