   283	function displayValue(value: unknown, maxLength: number, key?: string): string {
   284	  if (value === undefined || value === null) return '';
   285	  const redacted = redactForDisplay(value, key);
   286	  let rendered: string;
   287	  if (typeof redacted === 'string') {
   288	    rendered = redacted;
   289	  } else {
   290	    try {
   291	      rendered = JSON.stringify(redacted, null, 2);
   292	    } catch {
   293	      rendered = String(redacted);
   294	    }
   295	  }
   296	  return truncate(rendered, maxLength);
