   299	function approvalBlocks(row: {
   300	  content: string | null;
   301	  interaction_input_schema: Record<string, unknown> | null;
   302	  interaction_input: Record<string, unknown> | null;
   303	  metadata: Record<string, unknown> | null;
   304	}): LobuViewBlock[] {
   305	  const metadata = row.metadata ?? {};
   306	  const proposal = isRecord(metadata.proposal) ? metadata.proposal : null;
   307	  const current = isRecord(metadata.current) ? metadata.current : null;
   308	  const fields = isRecord(metadata.fields) ? metadata.fields : null;
   309	  const proposed = fields ?? proposal;
   310	  const blocks: LobuViewBlock[] = [];
   311	
   312	  if (proposed) {
   313	    const diffFields = Object.entries(proposed)
   314	      .filter(([key, value]) => !DIFF_ROUTING_KEYS.has(key) && value !== undefined)
   315	      .slice(0, DIFF_FIELD_MAX_ITEMS)
   316	      .map(([key, value]) => ({
   317	        label: truncate(key || 'field', TEXT_LABEL_MAX_LENGTH),
   318	        ...(current && current[key] !== undefined
   319	          ? { before: displayValue(current[key], TEXT_VALUE_MAX_LENGTH, key) }
   320	          : {}),
   321	        after: displayValue(value, TEXT_VALUE_MAX_LENGTH, key),
   322	      }));
   323	    if (diffFields.length > 0) blocks.push({ type: 'diff', fields: diffFields });
   324	  }
   325	
   326	  if (row.interaction_input_schema) {
   327	    blocks.push({
   328	      type: 'form',
   329	      schema: sanitizeFormSchema(row.interaction_input_schema) as Record<string, unknown>,
   330	      ...(row.interaction_input
   331	        ? {
   332	            initialValues: sanitizeFormInitialValues(row.interaction_input),
   333	          }
   334	        : {}),
   335	    });
   336	  } else if (row.interaction_input && Object.keys(row.interaction_input).length > 0) {
   337	    blocks.push({
   338	      type: 'code',
   339	      value: displayValue(row.interaction_input, CODE_VALUE_MAX_LENGTH),
   340	    });
   341	  }
   342	
   343	  if (blocks.length === 0) {
   344	    blocks.push({
   345	      type: 'text',
   346	      value: displayValue(row.content || 'Review this pending Lobu action.', TEXT_VALUE_MAX_LENGTH),
   347	      muted: true,
   348	    });
   349	  }
   350	  return blocks;
   351	}
   352	
   353	function sanitizeBlocks(blocks: LobuViewBlock[]): LobuViewBlock[] {
   354	  return blocks.slice(0, BLOCK_MAX_ITEMS).map((block) => {
   355	    if (block.type === 'text') {
   356	      return {
   357	        ...block,
   358	        ...(block.label ? { label: truncate(block.label, TEXT_LABEL_MAX_LENGTH) } : {}),
   359	        value: displayValue(block.value, TEXT_VALUE_MAX_LENGTH, block.label),
   360	      };

